import { BrowserRouter, Routes, Route } from 'react-router-dom';
import { HelmetProvider } from 'react-helmet-async';
import { ThemeProvider } from '@/components/theme-provider';
import { SideNav } from '@/components/side-nav';
import { MobileNav } from '@/components/mobile-nav';
import { BottomNav } from '@/components/bottom-nav';
import { WelcomeDialog } from '@/components/welcome-dialog';
import { Toaster } from '@/components/toaster';
import { ErrorBoundary } from '@/components/error-boundary';
import { TooltipProvider } from '@/components/ui/tooltip';
import { PWARegistration } from '@/components/pwa-registration';
import { PWAStatus } from '@/components/pwa-status';
import { DatabaseProvider } from '@/lib/db/db-provider';
import { P2PProvider } from '@/lib/db/p2p-provider';
import { NotificationsProvider } from '@/lib/notifications-provider';
import { lazy, Suspense } from 'react';

// Lazy-load all pages
const NovedadesPage = lazy(() => import('@/pages/novedades'));
const DireccionesPage = lazy(() => import('@/pages/settings/direcciones'));
const EstadisticasPage = lazy(() => import('@/pages/estadisticas'));
// Remove defunct GuardiasPage
const HistorialPage = lazy(() => import('@/pages/historial'));
const OrdenDelDiaPage = lazy(() => import('@/pages/orden-del-dia'));
const PersonalPage = lazy(() => import('@/pages/personal'));
const PlantillasPage = lazy(() => import('@/pages/plantillas'));
const ReporteFinalPage = lazy(() => import('@/pages/reporte-final'));
const SettingsPage = lazy(() => import('@/pages/settings'));
const SettingsBorrarDatosPage = lazy(() => import('@/pages/settings/borrar-datos'));
const SettingsP2PPage = lazy(() => import('@/pages/settings/p2p'));
const DocumentationPage = lazy(() => import('@/pages/documentation'));
const DocumentationAboutPage = lazy(() => import('@/pages/documentation/about'));
const DocumentationChangelogPage = lazy(() => import('@/pages/documentation/changelog'));
const DocumentationRoadmapPage = lazy(() => import('@/pages/documentation/roadmap'));
const DocumentationTemplateEnginePage = lazy(() => import('@/pages/documentation/template-engine'));
const DocumentationUserGuidePage = lazy(() => import('@/pages/documentation/user-guide'));
const OfflinePage = lazy(() => import('@/pages/offline'));

const PageLoader = () => (
  <div className="flex-1 p-6">
    <div className="h-full w-full bg-muted/20 rounded-lg animate-pulse" />
  </div>
);

function AppLayout() {
  return (
    <ThemeProvider attribute="class" defaultTheme="system" enableSystem disableTransitionOnChange>
      <DatabaseProvider>
        <NotificationsProvider>
          <P2PProvider>
            <TooltipProvider>
              <div className="flex min-h-screen w-full flex-col sm:flex-row" suppressHydrationWarning>
                <SideNav />
                <div className="flex flex-1 flex-col sm:pl-14">
                  <MobileNav />
                  <main className="flex-1 bg-muted/30 p-0 sm:p-0">
                    <ErrorBoundary name="MainContent">
                      <Suspense fallback={<PageLoader />}>
                        <Routes>
                          <Route path="/" element={<NovedadesPage />} />
                          <Route path="/settings/direcciones" element={<DireccionesPage />} />
                          <Route path="/estadisticas" element={<EstadisticasPage />} />
                          <Route path="/guardias" element={<NovedadesPage />} />
                          <Route path="/historial" element={<HistorialPage />} />
                          <Route path="/orden-del-dia" element={<OrdenDelDiaPage />} />
                          <Route path="/personal" element={<PersonalPage />} />
                          <Route path="/plantillas" element={<PlantillasPage />} />
                          <Route path="/reporte-final" element={<ReporteFinalPage />} />
                          <Route path="/settings" element={<SettingsPage />} />
                          <Route path="/settings/borrar-datos" element={<SettingsBorrarDatosPage />} />
                          <Route path="/settings/p2p" element={<SettingsP2PPage />} />
                          <Route path="/documentation" element={<DocumentationPage />} />
                          <Route path="/documentation/about" element={<DocumentationAboutPage />} />
                          <Route path="/documentation/changelog" element={<DocumentationChangelogPage />} />
                          <Route path="/documentation/roadmap" element={<DocumentationRoadmapPage />} />
                          <Route path="/documentation/template-engine" element={<DocumentationTemplateEnginePage />} />
                          <Route path="/documentation/user-guide" element={<DocumentationUserGuidePage />} />
                          <Route path="/offline" element={<OfflinePage />} />
                        </Routes>
                      </Suspense>
                    </ErrorBoundary>
                  </main>
                  <BottomNav />
                </div>
              </div>
              <WelcomeDialog />
              <PWARegistration />
              <PWAStatus />
              <Toaster />
            </TooltipProvider>
          </P2PProvider>
        </NotificationsProvider>
      </DatabaseProvider>
    </ThemeProvider>
  );
}

export default function App() {
  return (
    <HelmetProvider>
      <BrowserRouter>
        <AppLayout />
      </BrowserRouter>
    </HelmetProvider>
  );
}
